"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["13686"],{73688(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>u,frontMatter:()=>s,contentTitle:()=>d,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-on-request","title":"Submit the communication acknowledgement callback (internal variant) (adapter)","description":"Internal twin of /v1/communication/on_request: the provider acknowledgement Task bundle, operationId communicationOnRequestPostInternal.","source":"@site/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-on-request.mdx","sourceDirName":"nhcx/v1/api/communication/endpoints","slug":"/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-on-request","permalink":"/docs/pr-22/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-on-request","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the communication acknowledgement callback (internal variant) (adapter)","sidebar_label":"Submit the communication acknowledgement callback (internal variant) (adapter)","sidebar_class_name":"api-method api-method--post","description":"Internal twin of /v1/communication/on_request: the provider acknowledgement Task bundle, operationId communicationOnRequestPostInternal.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-communication.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the communication request (internal variant) (adapter)","permalink":"/docs/pr-22/docs/nhcx/v1/api/communication/endpoints/communication-internal-v1-communication-request"},"next":{"title":"Receive communication request","permalink":"/docs/pr-22/docs/nhcx/v1/api/communication/endpoints/communication-webhook-v1-communication-request"}}'),i=t(62540),o=t(43023),r=t(75064),c=JSON.parse('{"id":"communication_internal_v1_communication_on_request","module":"Communication","moduleId":"communication","kind":"operation","method":"POST","path":"/internal/v1/communication/on_request","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Communication acknowledgement callback (internal variant) (adapter)","title":"Submit the communication acknowledgement callback (internal variant) (adapter)","description":"Internal twin of /v1/communication/on_request: the provider acknowledgement Task bundle, operationId communicationOnRequestPostInternal.\\n\\n### Business purpose\\n\\nThis is the internal-path form of the provider acknowledgement that closes a payer communication. The OpenAPI document lists it with the same description and bare object request body as the public callback and distinguishes it only by the operationId suffix. Its business role is unchanged: give the payer auditable confirmation that a TAT alert, grievance, wallet or policy update or additional-information request reached the hospital, so adjudication and SLA tracking can proceed inside NHCX rather than over phone or email.\\n\\n### When to use\\n\\nUse it in the same circumstances as the public on_request callback: after receiving, acknowledging with a synchronous 202, and persisting a communication request, the provider posts a mirror-image Task bundle with the same reasonCode, Task.code poll, Task.intent proposal, Task.status completed and the same x-hcx-correlation_ID. The responder status is response.complete, response.partial or response.error. The specs do not say when the internal path is used instead of the public one; follow your onboarding instructions.\\n\\n### Preconditions\\n\\n- The inbound communication was decrypted and its correlation ID, status and workflow ID captured.\\n- A valid Bearer token and the payer\'s certificate for encrypting the acknowledgement.\\n- The acknowledgement bundle mirrors the request, provider Organisation first, timestamps updated.\\n- Protected header echoes the request\'s x-hcx-correlation_ID, carries a fresh x-hcx-API_call_ID, an IST timestamp and a responder status; x-hcx-workflow_ID is validated at the gateway.\\n- Confirm the internal prefix is the route you were onboarded to before using it.\\n\\n### Postconditions\\n\\nSame as the public callback: HTTP 202 with the StatusSuccessResponse envelope, or 400, 404 or 500 in the same shape; the bundle is forwarded to the payer, who links it to the original notification by correlation ID and by the shared claim or preauth reference. The underlying issue remains open until resolved through the preauth or claim path. No additional behaviour is documented for the internal variant.\\n\\n### Common mistakes\\n\\n- Expecting the internal path to relax any rule; it carries the same validation and the same errors (NHCX-1010 for an unknown correlation ID, NHCX-1011 for a bad status value).\\n- Minting a new correlation ID on the acknowledgement.\\n- Sending this call in place of the synchronous 202, which triggers the five-attempt retry loop and deletion of the request.\\n- Closing the case because Communication.status is completed.\\n- Using an unconfigurable path prefix that cannot switch between public and internal forms.\\n\\n### Best practices\\n\\n- Share one acknowledgement builder with the public callback; only the path differs.\\n- Return 202 within 30 seconds first, then post the acknowledgement asynchronously.\\n- Be idempotent on correlation ID; expect redeliveries.\\n- Route on Task.reasonCode and log reason, category, priority and correlation ID.\\n- Keep IST timestamps and a fresh API_call_ID on every call.\\n\\n### Related scenario\\n\\nA hospital integrator generating client code from the communicationhcxservice Swagger finds two acknowledgement operations, communicationOnRequestPost and communicationOnRequestPostInternal, with identical descriptions. The team implements one handler for inbound communications, answers 202 immediately, and posts the acknowledgement Task to the public /v1/communication/on_request path as the handbook documents, leaving the internal form selectable by configuration. When a walletupdate arrives for a patient mid-admission, the same handler refreshes the benefit cache before the enhancement request goes out on /v1/preauth/submit.\\n\\n### Specification\\n\\nChapter [Communication](/docs/nhcx/v1/reference/fhir/communication) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"},{"name":"x-hcx-sender_code","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"1000004446@hcx","type":"string"},{"name":"x-hcx-recipient_code","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"1518@hcx","type":"string"},{"name":"x-hcx-api_call_id","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-request_id","required":false,"description":"One per originating request. The Open Protocol page marks it Mandatory; the Technical Specifications page marks it Optional. Optional on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-correlation_id","required":true,"description":"The thread. See the rule below. Mandatory on the envelope.","example":"<uuid>","type":"string"},{"name":"x-hcx-workflow_id","required":false,"description":"Which step, or which case. See the two readings below. Optional on the envelope.","example":"15","type":"string"},{"name":"x-hcx-timestamp","required":true,"description":"See the format note below. Mandatory on the envelope.","example":"<iso timestamp>","type":"string"},{"name":"x-hcx-status","required":true,"description":"Where this message stands. Values below. Mandatory on the envelope.","example":"response.complete","type":"string"},{"name":"x-hcx-ben-abha-id","required":true,"description":"The beneficiary\'s ABHA number. Mandatory on every exchange, including those with no beneficiary in the payload. Mandatory on the envelope.","example":"91711234567890","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"payload","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"payload":"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag"},"responses":[{"status":"202","description":"Same as the public callback: HTTP 202 with the StatusSuccessResponse envelope, or 400, 404 or 500 in the same shape; the bundle is forwarded to the payer, who links it to the original notification by correlation id and by the shared claim or preauth reference.","example":{"timestamp":"25/08/2026 12:15:00:377","api_call_id":"d4e5f6a7-b8c9-0123-def0-234567890123","correlation_id":"22334455-6677-8899-aabb-ccddeeff0011","result":{"sender_code":"1000004446@hcx","recipient_code":"1518@hcx","entity_type":"task","protocol_status":"request.queued"},"error":{"code":"","message":""}}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/communication/on_request \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 15\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: response.complete\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/internal/v1/communication/on_request \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'x-hcx-sender_code: 1000004446@hcx\' \\\\\\n  --header \'x-hcx-recipient_code: 1518@hcx\' \\\\\\n  --header \'x-hcx-api_call_id: <uuid>\' \\\\\\n  --header \'x-hcx-request_id: <uuid>\' \\\\\\n  --header \'x-hcx-correlation_id: <uuid>\' \\\\\\n  --header \'x-hcx-workflow_id: 15\' \\\\\\n  --header \'x-hcx-timestamp: <iso timestamp>\' \\\\\\n  --header \'x-hcx-status: response.complete\' \\\\\\n  --header \'x-hcx-ben-abha-id: 91711234567890\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/internal/v1/communication/on_request\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"x-hcx-sender_code\\": \\"1000004446@hcx\\",\\n        \\"x-hcx-recipient_code\\": \\"1518@hcx\\",\\n        \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n        \\"x-hcx-request_id\\": \\"<uuid>\\",\\n        \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n        \\"x-hcx-workflow_id\\": \\"15\\",\\n        \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n        \\"x-hcx-status\\": \\"response.complete\\",\\n        \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/internal/v1/communication/on_request\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"x-hcx-sender_code\\": \\"1000004446@hcx\\",\\n    \\"x-hcx-recipient_code\\": \\"1518@hcx\\",\\n    \\"x-hcx-api_call_id\\": \\"<uuid>\\",\\n    \\"x-hcx-request_id\\": \\"<uuid>\\",\\n    \\"x-hcx-correlation_id\\": \\"<uuid>\\",\\n    \\"x-hcx-workflow_id\\": \\"15\\",\\n    \\"x-hcx-timestamp\\": \\"<iso timestamp>\\",\\n    \\"x-hcx-status\\": \\"response.complete\\",\\n    \\"x-hcx-ben-abha-id\\": \\"91711234567890\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"payload\\": \\"eyJhbGciOiJSU0EtT0FFUC0yNTYiLCJlbmMiOiJBMjU2R0NNIiwieC1oY3gtc2VuZGVyX2NvZGUiOiIxMDAwMDA0NDQ2QGhjeCJ9.encrypted_key.iv.ciphertext.tag\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let s={title:"Submit the communication acknowledgement callback (internal variant) (adapter)",sidebar_label:"Submit the communication acknowledgement callback (internal variant) (adapter)",sidebar_class_name:"api-method api-method--post",description:"Internal twin of /v1/communication/on_request: the provider acknowledgement Task bundle, operationId communicationOnRequestPostInternal.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-communication.yaml",generated:!0},d,h={},l=[];function p(e){return(0,i.jsx)(r.A,{operation:c})}function u(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(p,{...e})}):p(e)}}}]);